mkdir -p src && cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

// Test list for the MHPCO Claim Office kata.
//
// Observable contract for rejection cases: the specification states that the
// CLI "exits with a non-zero status code and writes an error description to
// stderr". The chosen reading is that the domain layer signals rejection by
// throwing an Error, and the CLI adapter translates a thrown Error into a
// non-zero exit code plus a stderr message. The specification does not
// establish an error subtype or message text, so tests assert `Error` only.

describe("MHPCO Claim Office", () => {
  describe("quote -- processing fee and empty policy", () => {
    it.todo("empty item list -> premium 5 G (only the processing fee)");
  });

  describe("quote -- main item base premiums (price list)", () => {
    it.todo("a plain sword -> premium 105 G (100 G base + 5 G fee)");
    it.todo("a plain amulet -> premium 65 G (60 G base + 5 G fee)");
    it.todo("a plain staff -> premium 85 G (80 G base + 5 G fee)");
    it.todo("a plain potion -> premium 45 G (40 G base + 5 G fee)");
  });

  describe("quote -- component base premiums", () => {
    it.todo("1 rune -> premium 30 G (25 G base + 5 G fee)");
    it.todo("1 moonstone -> premium 30 G (25 G base + 5 G fee)");
    it.todo("2 runes -> base premium 50 G -> premium 55 G");
    it.todo("3 runes -> base premium 60 G (block applies) -> premium 65 G");
    it.todo("4 runes -> base premium 100 G (no block -- block requires exactly 3) -> premium 105 G");
    it.todo("7 runes -> base premium 175 G -> premium 180 G");
    it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: different types) -> premium 80 G");
    it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks) -> premium 125 G");
    it.todo("3 moonstones -> base premium 60 G (block applies to moonstones too) -> premium 65 G");
  });

  describe("quote -- item-specific modifiers", () => {
    it.todo("a cursed sword -> 100 G base + 50 G curse surcharge + 5 G fee = 155 G");
    it.todo("a cursed amulet -> 60 G base + 30 G curse surcharge + 5 G fee = 95 G");
    it.todo("a sword with enchantment 5 -> high-enchantment surcharge applies: 100 + 30 + 5 = 135 G");
    it.todo("a sword with enchantment 4 -> no high-enchantment surcharge: 100 + 5 = 105 G");
    it.todo("a sword with enchantment 9 -> high-enchantment surcharge applies: 100 + 30 + 5 = 135 G");
    it.todo("a cursed sword with enchantment 5 -> both surcharges apply: 100 + 50 + 30 + 5 = 185 G");
    it.todo("a cursed sword with enchantment 4 -> only curse surcharge: 100 + 50 + 5 = 155 G");
  });

  describe("quote -- modifier scope on multi-item policies", () => {
    it.todo("cursed sword + plain amulet -> policy base 160 G, curse adds 50 G (50 % of the cursed item's base, not the policy total) -> 210 G + 5 G fee = 215 G");
    it.todo("plain sword + amulet with enchantment 5 -> policy base 160 G, high-enchantment adds 18 G (30 % of the amulet's base) -> 178 G + 5 G fee = 183 G");
  });

  describe("quote -- policy-wide modifiers", () => {
    it.todo("customer with 2 years with MHPCO -> loyalty discount applies: plain sword 100 - 20 + 5 = 85 G");
    it.todo("customer with 1 year with MHPCO -> no loyalty discount: plain sword 100 + 5 = 105 G");
    it.todo("customer with 3 years with MHPCO -> loyalty discount applies: plain sword 100 - 20 + 5 = 85 G");
    it.todo("loyalty discount is 20 % of the policy base premium (sum of all item base premiums): sword + amulet, 2 years -> 160 - 32 + 5 = 133 G");
    it.todo("first insurance surcharge: 10 % of the policy base premium applies to every quote -- each item in a quote is treated as a first insurance regardless of customer history");
    it.todo("follow-up contract discount: the second quote in a scenario gets 15 % off the policy base premium");
    it.todo("the third quote in a scenario also gets the 15 % follow-up discount");
    it.todo("the first quote in a scenario gets no follow-up discount");
    it.todo("the processing fee is added once at the very end, after all percentage modifiers");
  });

  describe("quote -- rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G -> final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote -- integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 -> premium 165 G (100 base + 50 curse + 10 first insurance = 160 + 5 fee)");
    it.todo("3-year customer, second quote, cursed steel sword, enchantment 7 -> premium 160 G (100 + 50 curse + 30 high enchantment - 20 loyalty + 10 first insurance - 15 follow-up = 155 + 5 fee)");
  });

  describe("quote -- rejections", () => {
    it.todo("a quote with an item of unknown type (e.g. broomstick) is rejected -- the domain throws an Error and no results are produced");
  });

  describe("claim -- standard reimbursement and deductible", () => {
    it.todo("regular steel sword, enchantment 3, damage 500 G -> payout 400 G (full reimbursement minus 100 G deductible)");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G -> payout 100 G (runes have no enchantment or material, so no special clause applies)");
    it.todo("damage below the deductible, e.g. 50 G -> payout 0 G (the payout is never negative)");
  });

  describe("claim -- high enchantment clause", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G -> payout 400 G (50 % first, then deductible: 500 - 100)");
    it.todo("steel sword, enchantment 8, damage 1000 G -> payout 400 G (threshold is enchantment >= 8)");
    it.todo("steel sword, enchantment 7, damage 1000 G -> payout 900 G (no high-enchantment clause: 1000 - 100)");
  });

  describe("claim -- dragon material clause", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G -> payout 700 G (full reimbursement, then deductible)");
    it.todo("dragon-material sword, enchantment 8, damage 1000 G -> payout 400 G (high-enchantment clause applies, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G -> payout 400 G (both clauses apply; the 50 % rule wins, then deductible)");
  });

  describe("claim -- deductible per damage event", () => {
    it.todo("a dragon attack damages an insured sword (500 G) and an insured amulet (300 G) -> payout 600 G (the 100 G deductible applies once per damaged item)");
  });

  describe("claim -- multiple items of the same type", () => {
    it.todo("a policy covering two swords has insurance sum 2000 G and cap 4000 G");
    it.todo("two sword damages against a two-sword policy -> each entry is a separate damage with its own deductible");
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) is rejected -- the domain throws an Error and the whole claim is rejected");
  });

  describe("claim -- insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet has insurance sum 1600 G and cap 3200 G");
    it.todo("a cursed sword (premium with modifiers 165 G) has cap 2000 G -- the cap is based on the unmodified insurance value");
    it.todo("a policy covering a sword and 3 runes has insurance sum 1750 G -- the block discount affects the premium only, not the insurance sum");
  });

  describe("claim -- cap exhaustion across successive claims", () => {
    it.todo("sword policy (cap 2000 G), first claim of 1500 G -> payout 1400 G, remainingCap 600 G");
    it.todo("sword policy (cap 2000 G), second claim of 1500 G after the first -> payout 600 G, remainingCap 0 G (the desired 1400 G is reduced to the remaining cap)");
    it.todo("a third claim after the cap is exhausted -> payout 0 G, remainingCap 0 G");
  });

  describe("claim -- rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G -> final payout 350 G (rounded down)");
    it.todo("intermediate amounts are kept as fractions; only the final payout is rounded");
  });

  describe("claim -- rejections", () => {
    it.todo("a damage entry whose item is not part of the policy (amulet damaged when only a sword is insured) is rejected -- the domain throws an Error");
    it.todo("a damage entry with an unknown item type is rejected -- the domain throws an Error");
    it.todo("a damage entry with amount: -200 is rejected -- the domain throws an Error");
    it.todo("a claim referencing a policy step index that is not a quote is rejected -- the domain throws an Error");
  });

  describe("scenario -- sequencing and result shape", () => {
    it.todo("results has the same length and order as steps");
    it.todo("a quote result contains only premium; a claim result contains payout and remainingCap");
    it.todo("the schema example scenario (5-year customer, amulet quote then 200 G amulet claim) produces a quote premium and a claim payout/remainingCap pair");
    it.todo("a claim refers to the policy created by the quote step at its zero-based policy index, not to the most recent quote");
  });

  describe("CLI", () => {
    it.todo("reads a JSON scenario from stdin and writes {results: [...]} as JSON to stdout");
    it.todo("exits with status 0 on a valid scenario");
    it.todo("on a rejected scenario exits with a non-zero status code, writes an error description to stderr, and writes no results to stdout");
  });
});
EOF
npx vitest run 2>&1 | tail -12

