    it.todo("3 runes -> base premium 60 G (block applies) -> premium 65 G");
    it.todo("4 runes -> base premium 100 G (no block -- block requires exactly 3) -> premium 105 G");
    it.todo("7 runes -> base premium 175 G -> premium 180 G");
    it.todo("2 runes + 1 moonstone -> base premium 75 G (no block: different types) -> premium 80 G");
    it.todo("3 runes + 3 moonstones -> base premium 120 G (two separate blocks) -> premium 125 G");
